// Leading-indicator screening experiments (plan 261109 S7), served by quantd as
// GET /api/v1/research/screens[/{id}]. Verdicts, gate results and the flow come from quant-signal
// verbatim; this module only names and formats them.
import type { Gate, GateFlowStep, RunMatrix, Verdict } from "./data";

export type ScreenVerdict = "채택" | "조건부" | "시계 한정" | "기각" | "판정 불가";

export interface ScreenTrial {
	h: number;
	oos_obs: number;
	oos_years: number;
	fold_sign_agree: number | null;
	ic: number | null;
	t_nw: number | null;
	ci_lo: number | null;
	ci_hi: number | null;
	partial_ic: number | null;
	ic_up: number | null;
	ic_down: number | null;
	ann_ret: number | null;
	sharpe: number | null;
	exposure: number | null;
	dsr: number | null;
	pass: boolean;
	miss: string;
	miss_gate: number | null;
	train_sign: number;
	folds: { year: number; ic: number | null; n: number; train_sign: number }[];
}

export interface ScreenFeature {
	code: string;
	feature: string;
	family: string;
	verdict: ScreenVerdict;
	reason: string;
	lead_h: number;
	tradeable?: boolean;
	test_years?: [number, number];
	trials: ScreenTrial[];
}

export interface ScreenDoc {
	experiment_id: string;
	market: string;
	title: string;
	hypothesis: string;
	sealed_at: string;
	note: string;
	unit: "D" | "H";
	horizons: number[];
	swing_horizons: number[];
	test_years: [number, number];
	regime: string | null;
	fixed_sign: number | null;
	cost_per_side: number;
	gates: { id: string; name: string; rule: string; threshold: number }[];
	gate_status: { id: string; status: Gate["status"]; reason: string }[];
	gate_flow: GateFlowStep[];
	state: "연구통과" | "평가완료" | "연구기각";
	trials_total: number;
	trials_counted: number;
	asof_violations: number;
	gate_sha256: string;
	result_hash: string;
	features: ScreenFeature[];
}

export interface ScreenSummary {
	id: string;
	market: string;
	title: string;
	state: ScreenDoc["state"];
	hypothesis: string;
	sealedAt: string;
	unit: "D" | "H";
	candidates: number;
	trialsTotal: number;
	trialsCounted: number;
	verdicts: Partial<Record<ScreenVerdict, number>>;
	resultHash: string;
	gateSha256: string;
}

/** Display name and one-line definition of each indicator (the screen's own names stay as the source). */
export const FEATURE_LABEL: Record<string, [string, string]> = {
	mom_5: ["5일 모멘텀", "5일 로그 수익률"],
	mom_21: ["21일 모멘텀", "21일 로그 수익률"],
	vol_21: ["21일 변동성", "일간 수익률 21일 표준편차"],
	volume_z90: ["거래량 z", "24시간 거래량(로그)의 90일 z점수"],
	funding_1d: ["펀딩 1일", "Binance 무기한 펀딩비 24시간 평균"],
	funding_7d: ["펀딩 7일", "펀딩비 7일 평균"],
	funding_z90: ["펀딩 z", "펀딩 1일의 90일 z점수"],
	premium_1d: ["베이시스 1일", "무기한 가격의 지수 대비 프리미엄 24시간 평균"],
	premium_z90: ["베이시스 z", "베이시스 1일의 90일 z점수"],
	oi_chg_1d: ["OI 1일 변화", "미결제약정 1일 로그 변화"],
	oi_chg_7d: ["OI 7일 변화", "미결제약정 7일 로그 변화"],
	oi_x_trend_7d: ["OI × 추세", "OI 7일 변화에 7일 가격 방향 부호를 곱한 값"],
	top_position_ls_z90: ["상위 트레이더 롱숏 z", "상위 계정 포지션 롱숏비의 90일 z점수"],
	global_ls_z90: ["전체 롱숏 z", "전체 계정 롱숏비의 90일 z점수"],
	taker_ratio_7d: ["테이커 매수비 7일", "테이커 매수/매도 거래량 비 7일 평균"],
	kimchi_1d: ["김프 1일", "업비트 원화가 ÷ (바이낸스가 × 원달러) − 1"],
	kimchi_7d: ["김프 7일", "김프 1일의 7일 평균"],
	kimchi_z180: ["김프 z", "김프 1일의 180일 z점수"],
	follow_next: [
		"그의 방향 따라가기",
		"직전 칸의 순진입 방향(롱 +, 숏 −)을 한 칸 늦게 따라간다. 체결이 실시간 공개되지 않으므로 참고 행이다",
	],
	mimic_score: ["모방 점수", "그의 진입 방향을 설명한 지표 z점수의 부호 합(학습 2018~2020)"],
	ret_1h: ["1시간 수익률", "직전 1시간 로그 수익률"],
	ret_4h: ["4시간 수익률", "직전 4시간 로그 수익률"],
	ret_24h: ["24시간 수익률", "직전 24시간 로그 수익률"],
	vol_24h: ["24시간 변동성", "시간 수익률 24개 표준편차"],
	volume_z168: ["거래량 z", "1시간 거래량(로그)의 168시간 z점수"],
	funding_last: ["최근 펀딩", "마지막 정산 펀딩비"],
	premium_1h: ["베이시스 1시간", "직전 1시간 프리미엄"],
	premium_24h: ["베이시스 24시간", "프리미엄 24시간 평균"],
	oi_chg_4h: ["OI 4시간 변화", "미결제약정 4시간 로그 변화"],
};

export const FAMILY_LABEL: Record<string, string> = {
	price: "가격·거래량",
	funding: "펀딩",
	basis: "베이시스",
	oi: "미결제약정",
	long_short: "롱숏비",
	kimchi: "김프",
	expert: "워뇨띠 체결",
	mimic: "모방 지표",
};

export const featureName = (f: ScreenFeature) => FEATURE_LABEL[f.feature]?.[0] ?? f.feature;
export const featureDef = (f: ScreenFeature) => FEATURE_LABEL[f.feature]?.[1] ?? "";

/** Badge kind of a screen verdict (color plus the verdict word). */
export function verdictKind(v: ScreenVerdict): Verdict | "waiting" {
	if (v === "채택") return "passed";
	if (v === "기각") return "rejected";
	if (v === "판정 불가") return "waiting";
	return "undecided";
}

export function stateKind(s: ScreenDoc["state"]): Verdict {
	return s === "연구통과" ? "passed" : s === "연구기각" ? "rejected" : "undecided";
}

export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

export function num(v: number | null | undefined, digits = 3): string {
	if (v == null || !Number.isFinite(v)) return "—";
	const s = v.toFixed(digits);
	return v > 0 ? `+${s}` : s.replace("-", "−");
}

export function pctOf(v: number | null | undefined, digits = 1): string {
	if (v == null || !Number.isFinite(v)) return "—";
	const s = (v * 100).toFixed(digits);
	return v > 0 ? `+${s}%` : `${s.replace("-", "−")}%`;
}

/** Gate nodes for GateFlow: names and rules from the document, status from `gate_status`. */
export function screenGates(doc: ScreenDoc): Gate[] {
	return doc.gates.map((g) => {
		const s = doc.gate_status.find((x) => x.id === g.id);
		return {
			id: g.id,
			name: g.name,
			definition: `${g.id}: ${g.rule}.`,
			status: s?.status ?? "waiting",
			reason: s?.reason ?? "",
		};
	});
}

/**
 * The matrix: one row per candidate at horizon `h` ("lead" = the horizon its verdict is about), one
 * column per test year; a cell is that year's signed rank IC ×100 (0.10 shows as +10).
 */
export function screenMatrix(doc: ScreenDoc, h: "lead" | number = "lead"): RunMatrix {
	const years = new Set<number>();
	for (const f of doc.features) for (const t of f.trials) for (const fold of t.folds) years.add(fold.year);
	const folds = [...years].sort().map((year) => ({ id: String(year), year }));
	return {
		phase: "screen",
		stresses: [{ id: "ic", label: "" }],
		folds,
		rows: doc.features.map((f) => {
			const trial = h === "lead" ? leadTrial(f) : f.trials.find((t) => t.h === h);
			return {
				candidate: f.code,
				label: trial ? `${trial.h}${doc.unit}` : "—",
				cells: (trial?.folds ?? [])
					.filter((fold) => fold.ic != null)
					.map((fold) => ({
						stress: "ic",
						year: fold.year,
						diff: fold.ic! * 100,
						gate0: "passed" as const,
					})),
			};
		}),
		note: "",
	};
}

