import { describe, expect, it } from "vitest";
import {
	curveView,
	dateLabel,
	niceTicks,
	screenRule,
	trialAt,
	type ScreenDoc,
	type ScreenFeature,
	type ScreenTrial,
} from "./screen";

const trial = (over: Partial<ScreenTrial> = {}): ScreenTrial =>
	({ h: 4, train_sign: 1, folds: [{ year: 2022, ic: 0.1, n: 100, train_sign: 1 }], ...over }) as ScreenTrial;
const feature = (over: Partial<ScreenFeature> = {}): ScreenFeature =>
	({
		code: "M1",
		feature: "mimic_score",
		lead_h: 4,
		trials: [trial({ h: 1 }), trial({ h: 4 })],
		...over,
	}) as ScreenFeature;
const doc = (over: Partial<ScreenDoc> = {}): ScreenDoc =>
	({ unit: "H", cost_per_side: 0.001, fixed_sign: null, regime: null, ...over }) as ScreenDoc;

describe("screen curve", () => {
	it("picks round ticks that include zero", () => {
		expect(niceTicks(-375, 136)).toEqual([-300, -200, -100, 0, 100]);
		expect(niceTicks(0, 90)).toEqual([0, 20, 40, 60, 80]);
	});

	it("labels dates with dots so the chart never reads a day 01 as a January tick", () => {
		expect(dateLabel(Date.UTC(2022, 0, 1))).toBe("2022.01.01");
		expect(dateLabel(Date.UTC(2022, 0, 1)).endsWith("-01")).toBe(false);
	});

	it("turns the fraction sums into percent and carries over a missing point", () => {
		const t = [1, 2, 3].map((k) => Date.UTC(2022, 0, k));
		const view = curveView(trial({ curve: { t, rule: [0, null, -3.75], hold: [0, 0.5, 1.36] } }));
		expect(view?.rule).toEqual([0, 0, -375]);
		expect(view?.hold[2]).toBeCloseTo(136);
		expect(view?.ticks).toContain(0);
		expect(view?.labels).toHaveLength(3);
	});

	it("has no view without a curve or with fewer than two points", () => {
		expect(curveView(undefined)).toBeNull();
		expect(curveView(trial())).toBeNull();
		expect(curveView(trial({ curve: null }))).toBeNull();
		expect(curveView(trial({ curve: { t: [1], rule: [0], hold: [0] } }))).toBeNull();
	});

	it("falls back to the lead trial for a horizon the feature lacks", () => {
		const f = feature();
		expect(trialAt(f, 1).h).toBe(1);
		expect(trialAt(f, "lead").h).toBe(4);
		expect(trialAt(f, 24).h).toBe(4);
	});
});

describe("screen rule tiles", () => {
	const byId = (tiles: ReturnType<typeof screenRule>, id: string) => tiles.find((x) => x.id === id)!;

	it("reads a fixed-sign document as 'above 0 follows the value'", () => {
		const tiles = screenRule(doc({ fixed_sign: 1 }), feature(), trial());
		expect(tiles.map((x) => x.group)).toEqual(["entry", "entry", "fill", "exit"]);
		expect(byId(tiles, "direction")).toMatchObject({ name: "기준 위면 롱", label: "순방향" });
		expect(byId(tiles, "direction").tip).toContain("+1로 고정");
		expect(byId(tiles, "fill").name).toBe("편도 10bp");
		expect(byId(tiles, "hold").name).toBe("4H 보유");
	});

	it("flips the sides when the train sign is negative and says so when the sign changed by year", () => {
		const contrarian = screenRule(doc(), feature(), trial({ train_sign: -1 }));
		expect(byId(contrarian, "direction")).toMatchObject({ name: "기준 위면 숏", label: "역추세" });
		const changed = screenRule(
			doc(),
			feature(),
			trial({
				folds: [
					{ year: 2022, ic: 0.1, n: 100, train_sign: 1 },
					{ year: 2023, ic: 0.1, n: 100, train_sign: -1 },
				],
			}),
		);
		expect(byId(changed, "direction").label).toBe("부호 바뀜");
	});

	it("adds the regime tile only for a down-regime gate and marks a reference row", () => {
		expect(screenRule(doc({ regime: "down" }), feature(), trial()).map((x) => x.id)).toContain("regime");
		expect(screenRule(doc(), feature(), trial()).map((x) => x.id)).not.toContain("regime");
		expect(byId(screenRule(doc(), feature({ tradeable: false }), trial()), "indicator").label).toBe("참고 지표");
	});
});

